INSERT INTO public.categories (id, name, slug, description, icon, sort_order, is_active) VALUES
  ('11111111-1111-1111-1111-111111111101', 'อาหารตามสั่ง', 'made-to-order', 'ผัดกะเพรา ข้าวผัด เต้าหู้ทรงเครื่อง ทำสดจานต่อจาน', 'Flame', 1, true),
  ('11111111-1111-1111-1111-111111111102', 'อาหารจานเดียว', 'single-dish', 'ข้าวราดแกง ข้าวมันไก่ ข้าวยำไก่แซ่บ อิ่มไวทันเข้าเรียน', 'Utensils', 2, true),
  ('11111111-1111-1111-1111-111111111103', 'ก๋วยเตี๋ยว', 'noodles', 'บะหมี่เกี๊ยวหมูแดง-หมูกรอบ สุกี้ ต้มเลือดหมู และราเมนเส้นสด', 'Soup', 3, true),
  ('11111111-1111-1111-1111-111111111104', 'อาหารอีสาน', 'isaan-food', 'ส้มตำ ลาบ น้ำตก ไก่ย่าง และยำรสจัดจ้านขวัญใจเด็กบางมด', 'Sparkles', 4, true),
  ('11111111-1111-1111-1111-111111111105', 'อาหารฮาลาล', 'halal-food', 'ข้าวหมกไก่ ข้าวมันไก่ฮาลาล ก๋วยเตี๋ยวเนื้อ และข้าวแกงอิสลาม', 'ShieldCheck', 5, true),
  ('11111111-1111-1111-1111-111111111106', 'ของทอด', 'fried-snacks', 'ไก่ทอดหาดใหญ่ หมูทอดน้ำปลาพริก ลูกชิ้นทอด และทาโกยากิ', 'Drumstick', 6, true),
  ('11111111-1111-1111-1111-111111111107', 'ขนมและเบเกอรี่', 'bakery-desserts', 'เครปเย็น ขนมปังปิ้ง โมจิครีมชีส ซอฟต์คุกกี้ และขนมไทยตลาดนัด', 'Croissant', 7, true),
  ('11111111-1111-1111-1111-111111111108', 'เครื่องดื่ม', 'beverages', 'น้ำผลไม้ปั่น น้ำสมุนไพร นมสด และอิตาเลียนโซดาสดชื่น', 'CupSoda', 8, true),
  ('11111111-1111-1111-1111-111111111109', 'กาแฟ', 'coffee', 'คาเฟ่และร้านกาแฟสดรอบรั้ว มจธ.', 'Coffee', 9, true),
  ('11111111-1111-1111-1111-111111111110', 'ชานม', 'milk-tea', 'ชานมไข่มุก ชาชีส มัทฉะลาเต้ และชาผลไม้', 'GlassWater', 10, true),
  ('11111111-1111-1111-1111-111111111111', 'ผลไม้', 'fruits', 'ผลไม้สดพร้อมทาน ผลไม้ตามฤดูกาล และน้ำผลไม้คั้นสด', 'Apple', 11, true),
  ('11111111-1111-1111-1111-111111111112', 'เสื้อผ้า', 'clothing', 'เสื้อยืด เสื้อเชิ้ต กางเกง และชุดนักศึกษาในตลาดนัด มจธ.', 'Shirt', 12, true),
  ('11111111-1111-1111-1111-111111111113', 'แฟชั่น', 'fashion', 'กระเป๋าผ้า หมวก เครื่องประดับ และงานแฮนด์เมด', 'ShoppingBag', 13, true),
  ('11111111-1111-1111-1111-111111111114', 'สินค้าอุปโภค', 'general-goods', 'ของใช้หอพัก อุปกรณ์การเรียน และสินค้าชุมชน', 'Package', 14, true),
  ('11111111-1111-1111-1111-111111111115', 'อื่น ๆ', 'others', 'บริการและร้านค้าเบ็ดเตล็ดภายในมหาวิทยาลัย', 'Sparkle', 15, true)
INSERT INTO public.market_events (name, market_type, day_of_week, start_time, end_time, setup_time, location, description, status) VALUES
  ('ตลาดนัดสินค้าชุมชน (วันอังคาร)', 'community_tue', 2, '07:00', '17:00', '05:30', 'ลานชั้น 1 อาคารจอดรถ 14 ชั้น (S2) มจธ. บางมด', 'ตลาดนัดส่งเสริมผู้ประกอบการชุมชน ขนาดล็อก 180x200 ซม.', 'active'),
  ('ตลาดนัด มจธ. (วันพุธ)', 'kmutt_wed_thu', 3, '07:00', '17:00', '05:30', 'ลานชั้น 1 อาคารจอดรถ 14 ชั้น (S2) มจธ. บางมด', 'ตลาดนัดกลางสัปดาห์ ค่าบริหารพื้นที่ อาหาร 250 บ./วัน, แฟชั่น 200 บ./วัน, ไฟฟ้า 50 บ./จุด', 'active'),
  ('ตลาดนัด มจธ. (วันพฤหัสบดี)', 'kmutt_wed_thu', 4, '07:00', '17:00', '05:30', 'ลานชั้น 1 อาคารจอดรถ 14 ชั้น (S2) มจธ. บางมด', 'ตลาดนัด มจธ. วันพฤหัสบดี บริเวณลานชั้น 1 อาคารจอดรถ S2', 'active');
